// Read ONLY the uncompressed ZIP format generated by FEP Editor PRO.
// Strict bounds, CRC-32 verification and path checks prevent malformed archives.
const decoder=new TextDecoder('utf-8',{fatal:true});
export function crc32(bytes){let crc=0xffffffff;for(const b of bytes){crc^=b;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return(crc^0xffffffff)>>>0}
export async function readFepLibraryZip(input,{maxBytes=100*1024*1024,maxFiles=100}={}){
 const buffer=input instanceof ArrayBuffer?input:await input.arrayBuffer();
 if(buffer.byteLength>maxBytes||buffer.byteLength<52)throw Error('Respaldo ZIP vacío o demasiado grande');
 const bytes=new Uint8Array(buffer),d=new DataView(buffer),files=new Map();let at=0,total=0;
 while(at+4<=bytes.length){
  const marker=d.getUint32(at,true);
  if(marker===0x02014b50||marker===0x06054b50)break;
  if(marker!==0x04034b50||at+30>bytes.length)throw Error('ZIP dañado: cabecera no válida');
  const flags=d.getUint16(at+6,true),method=d.getUint16(at+8,true);
  const expectedCrc=d.getUint32(at+14,true),compressed=d.getUint32(at+18,true),original=d.getUint32(at+22,true);
  const nameLength=d.getUint16(at+26,true),extraLength=d.getUint16(at+28,true);
  if(flags!==0||method!==0||compressed!==original)throw Error('El ZIP no es un respaldo local compatible');
  const start=at+30+nameLength+extraLength,end=start+compressed;
  if(nameLength<1||end>bytes.length||compressed>30*1024*1024)throw Error('Archivo ZIP fuera de límites');
  const name=decoder.decode(bytes.subarray(at+30,at+30+nameLength));
  if(!/^[a-zA-Z0-9_./-]+$/.test(name)||name.includes('..')||files.has(name))throw Error('Nombre o ruta ZIP no admitidos');
  const data=bytes.subarray(start,end);
  if(crc32(data)!==expectedCrc)throw Error('Archivo ZIP corrupto: '+name);
  total+=compressed;if(total>maxBytes||files.size>=maxFiles)throw Error('El ZIP supera el límite de seguridad');
  files.set(name,decoder.decode(data));at=end;
 }
 if(files.size<2||!files.has('manifest.json'))throw Error('No es una biblioteca FEP válida');
 // Verify that the central directory exists to reject incomplete archives.
 if(at+4>bytes.length||d.getUint32(at,true)!==0x02014b50)throw Error('ZIP incompleto: falta directorio central');
 const manifest=JSON.parse(files.get('manifest.json'));
 if(manifest.format!=='fep-library'||manifest.version!==1||!Number.isInteger(manifest.count)||manifest.count<1||manifest.count>95||manifest.count!==manifest.projects?.length||manifest.count!==files.size-1)throw Error('Manifiesto de respaldo incompatible');
 const used=new Set();
 for(const entry of manifest.projects){
  if(typeof entry.name!=='string'||entry.name.length>200||typeof entry.file!=='string'||!/^proyectos\/proyecto_\d{3}\.json$/.test(entry.file)||used.has(entry.file)||!files.has(entry.file))throw Error('Índice del respaldo inválido');
  if(typeof entry.digest!=='string'||!/^[a-f0-9]{64}$/.test(entry.digest))throw Error('Hash de respaldo inválido');
  used.add(entry.file);
 }
 return {manifest,files};
}
